import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import {join} from 'node:path';
import {TestIngress} from '../proposals/new-files/scripts/probe-ingress.mjs';import {EventHook,MonitorHook,ReaderHook} from '../proposals/selected-hooks.mjs';
async function fixture(extra={}){
 const root=await fs.mkdtemp(join(os.tmpdir(),'fix1-route-'));let now=Date.now(),received=[],submits=[],writes=0;const token='a'.repeat(32),identity={appId:'app',tenantKey:'tenant',scope:'tenant/app',userId:'ou_synthetic_a'},events=new Map();
 const options={file:join(root,'claims.sqlite'),appId:'app',tenantId:'tenant',enabled:true,windows:[{token,userId:identity.userId,alias:'A',start:now-100,end:now+10000}],clock:()=>now,ioTimeoutMs:25,verify:async id=>({...events.get(id),appId:'app',tenantKey:'tenant'}),enqueue:async x=>submits.push(x),...extra};
 let gate=new TestIngress(options);const state={sources:[],cases:[],audit:[],revision:0};const control={enabled:true,personal:true,revision:0,generation:'g',identity:{scope:identity.scope,userId:identity.userId},startedAt:new Date(now-1000).toISOString(),eventPush:{enabled:true},intervalSeconds:60};
 const store={load:()=>state,transaction:fn=>fn(),save:next=>{Object.assign(state,next);writes++;}};const domain={applySourceSubjectAssociation(){},validateState:()=>[],safeFeishuUrl:()=>''};
 const event=(action,id='om_'+events.size,more={})=>{const e={message_id:id,sender_id:identity.userId,sender_type:'user',chat_id:'oc_synthetic',chat_type:'p2p',content:action,create_time:String(now),...more};events.set(id,e);return e;};
 const route=async(e,scope=identity,key='im.message.receive_v1')=>{const m=gate.match({identity:scope,event:e,key});if(!m)return {handled:false};return gate.handle(m);};
 const hook=new EventHook();Object.assign(hook,{store,domain,monitor:{control:()=>control,save(){}},testIngress:gate,client:{identity:async()=>identity,run:async args=>{const id=args.includes('--message-ids')?args[args.indexOf('--message-ids')+1]:JSON.parse(args[args.indexOf('--params')+1]).message_ids[0],e=events.get(id);return args[1]==='+messages-mget'?{messages:[{message_id:id,content:e.content}]}:{items:[{message_id:id,chat_id:e.chat_id,sender:{id:e.sender_id},create_time:e.create_time,msg_type:'text'}]};}},onMessage:async x=>received.push(x)});
 return {root,options,token,identity,events,event,route,hook,state,store,domain,control,submits,get gate(){return gate;},get writes(){return writes;},advance(ms){now+=ms;},now:()=>now,async restart(){await gate.close();gate=new TestIngress({...options,enabled:false,windows:[]});hook.testIngress=gate;},async close(){await gate.close();await fs.rm(root,{recursive:true,force:true});}};
}
const command=(f,x)=>'#PROBE '+f.token+' '+x;
 test('candidate event hook diverts only explicit verified sessions before formal save',async()=>{const f=await fixture();try{await f.hook.ingest('w','im.message.receive_v1',f.event('普通业务反馈'));assert.equal(f.writes,1);await f.hook.ingest('w','im.message.receive_v1',f.event(command(f,'BEGIN')));await f.hook.ingest('w','im.message.receive_v1',f.event(command(f,'RUN')));assert.equal(f.submits.length,1);assert.equal(f.writes,1);assert.equal(f.state.sources.length,1);}finally{await f.close();}});
 test('same whitelist user ordinary business remains ordinary',async()=>{const f=await fixture();try{await f.route(f.event(command(f,'BEGIN')));assert.equal((await f.route(f.event('普通业务，不属于测试'))).handled,false);}finally{await f.close();}});
 test('wrong tenant, wrong actor and group are quarantined, never executed',async()=>{const f=await fixture();try{for(const [more,scope] of [[{}, {...f.identity,tenantKey:'other'}],[{sender_id:'ou_other'},f.identity],[{chat_type:'group'},f.identity]])assert.equal((await f.route(f.event(command(f,'RUN'),undefined,more),scope)).status,'quarantined_identity');assert.equal(f.submits.length,0);}finally{await f.close();}});
 test('unverified sender mismatch is held before dispatch',async()=>{const f=await fixture({verify:async()=>({})});try{assert.equal((await f.route(f.event(command(f,'BEGIN')))).status,'quarantined_readback');assert.equal(f.submits.length,0);}finally{await f.close();}});
 test('missing timestamp cannot bypass test window',async()=>{const f=await fixture();try{assert.equal((await f.route(f.event(command(f,'BEGIN'),undefined,{create_time:'bad'}))).status,'quarantined_identity');}finally{await f.close();}});
 test('worker offline and timeout cannot fall back to formal ingestion',async()=>{for(const enqueue of [async()=>{throw Error('offline')},()=>new Promise(()=>{})]){const f=await fixture({enqueue});try{await f.route(f.event(command(f,'BEGIN')));const r=await f.route(f.event(command(f,'RUN')));assert.equal(r.status,'worker_unknown');assert.equal(r.handled,true);assert.equal(f.writes,0);}finally{await f.close();}}});
 test('duplicates and late test messages remain quarantined after disable/restart',async()=>{const f=await fixture();try{await f.route(f.event(command(f,'BEGIN')));const e=f.event(command(f,'RUN'),'om_stable');await f.route(e);await f.restart();assert.equal((await f.route(e)).status,'duplicate');assert.equal((await f.route(f.event(command(f,'RUN')))).status,'held_disabled');assert.equal((await f.route(f.event('新普通业务'))).handled,false);assert.equal(f.submits.length,1);}finally{await f.close();}});
 test('expiry retains test namespace while ordinary business continues',async()=>{const f=await fixture();try{await f.route(f.event(command(f,'BEGIN')));f.advance(10001);assert.equal((await f.route(f.event(command(f,'RUN')))).status,'held_window');assert.equal((await f.route(f.event('正常业务'))).handled,false);}finally{await f.close();}});
 test('minutes event never enters test dispatcher',async()=>{const f=await fixture();try{assert.equal((await f.route({note_token:'synthetic-note'},f.identity,'vc.note.generated_v1')).handled,false);assert.equal(f.submits.length,0);}finally{await f.close();}});
 test('poll-first observation suppresses ingestion but later real-shaped event may claim once',async()=>{const f=await fixture();try{const e=f.event(command(f,'BEGIN'),'om_poll');const kept=await f.gate.filterPolled({identity:f.identity,messages:[{message_id:e.message_id,content:e.content,chat_id:e.chat_id,sender:{id:e.sender_id},create_time:e.create_time}]});assert.equal(kept.length,0);assert.equal((await f.route(e)).status,'activated');}finally{await f.close();}});
 test('candidate polling hook excludes test bot output and keeps ordinary source',async()=>{const f=await fixture();try{const messages=[{message_id:'om_bot',content:command(f,'RESULT synthetic'),chat_id:'oc_synthetic',sender:{id:'bot_synthetic'},create_time:String(f.now()-1),channels:['private']},{message_id:'om_normal',content:'普通反馈',chat_id:'oc_other',sender:{id:'ou_other'},create_time:String(f.now()-1),channels:['private']}];const h=new MonitorHook();Object.assign(h,{store:f.store,domain:f.domain,testIngress:f.gate,clock:()=>new Date(f.now()).toISOString(),capture(){},control:()=>f.control,save(){},status:()=>({}),reader:{identity:async()=>f.identity,read:async()=>({messages,complete:true,issues:[]})}});await h.run('w',structuredClone(f.control),new AbortController().signal);assert.equal(f.state.sources.length,1);assert.equal(f.state.sources[0].excerpt,'普通反馈');}finally{await f.close();}});
 test('candidate reader excludes reserved test mentions before group discovery triggers',async()=>{const f=await fixture();try{let triggers;const rows=[{message_id:'om_reserved',content:command(f,'BEGIN'),chat_id:'oc_synthetic',sender:{id:f.identity.userId},create_time:String(f.now())},{message_id:'om_ordinary',content:'普通提及',chat_id:'oc_group',sender:{id:'ou_other'},create_time:String(f.now())}];const h=new ReaderHook();h.client={run:async args=>args[1]==='+messages-search'?{messages:rows,has_more:false}:{items:rows},readGroup:async input=>{triggers=input.triggers;return {messages:[],issues:[],state:{}};}};const r=await h.read({start:new Date(f.now()-1000).toISOString(),end:new Date(f.now()+1000).toISOString(),signal:new AbortController().signal,discoverGroups:true,filterTestMessages:messages=>f.gate.filterPolled({identity:f.identity,messages})});assert.deepEqual(triggers.map(x=>x.message_id),['om_ordinary']);assert.deepEqual(r.messages.map(x=>x.message_id),['om_ordinary']);}finally{await f.close();}});
